mapper.select:
/*selectMasterWmGiCartRegPopList*/ SELECT CQDT.BUYER_ITEM_NO, CQDT.DESCRIPTION, CQDT.MAKER_NAME, CASE WHEN STCK.MAX_STOCK_QTY-STCK.AVAIL_QTY < 0 THEN 0 ELSE STCK.MAX_STOCK_QTY-STCK.AVAIL_QTY END AS COM_STCK_QTY, CQDT.LIST_PRICE, STCK.SAFE_STOCK_QTY,
(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = CQDT.AGENT) AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = CQDT.AGENT) AS AGENT_TEL, DECODE(CQDT.PROCESS_TYPE,'1','재고상품','3','VMI상품') AS INCOME_PATH, CQDT.SPECIFICATION, CQDT.UNIT_MEASURE, STCK.AVAIL_QTY, STCK.MIN_ORDER_QTY, STCK.MAX_STOCK_QTY, CQDT.CONTRACT_NO, CQDT.CONTRACT_SEQ, CQDT.BUYER_ITEM_NO, CQDT.AGENT, CQDT.PROCESS_TYPE FROM ICOMCQDT CQDT, WMSSTCK STCK WHERE BUYER =#{st_warehouse_code} AND CQDT.BUYER = STCK.WAREHOUSE_CODE AND CQDT.BUYER_ITEM_NO = STCK.STDCATLG_ID
AND CQDT.BUYER_ITEM_NO IN
#{STDCATLG_ID}


SELECT COUNT(*) AS COUNTVALUE FROM ICOMCART 
 WHERE BUYER = #{st_warehouse_code}				
	AND USER_ID =  #{st_USER_ID}			
	AND CONTRACT_NO = #{CONTRACT_NO}			
	AND CONTRACT_SEQ =#{CONTRACT_SEQ}	
   AND USE_FLAG = 'C'
